\begin{gathered}
\frac{\Gamma\equiv_\Sigma\Delta\quad\Gamma\vdash J}{\Delta\vdash J}\qquad
\frac{\Gamma\vdash\sigma:\Delta\quad\Delta\vdash J}{\Gamma\vdash J[\sigma]}\\
\frac{\Gamma,x:A,y:A,\Delta\vdash J}{\Gamma,x:A,\Delta[x/y]\vdash J[x/y]}\qquad
\frac{\Gamma,x:A,y:B,\Delta\vdash J\quad x\notin\operatorname{FV}(B)\quad\Gamma,y:B,x:A,\Delta\ \mathsf{ctx}}
{\Gamma,y:B,x:A,\Delta\vdash J}.
\end{gathered}

\begin{gathered}
\frac{\Gamma\vdash A=A':\mathsf{Ty}\quad\Gamma,x:A\vdash B=B':\mathsf{Ty}}
{\Gamma\vdash\mathcal B(x:A).B=\mathcal B(x:A').B':\mathsf{Ty}}
\quad(\mathcal B\in\{\Pi,\Sigma\})\\
\frac{\Gamma\vdash A=A':\mathsf{Ty}\quad\Gamma\vdash a=a':A\quad\Gamma\vdash b=b':A}
{\Gamma\vdash\operatorname{Eq}_A(a,b)=\operatorname{Eq}_{A'}(a',b'):\mathsf{Ty}}\\
\frac{\Gamma\vdash A=A':\mathsf{Ty}\quad\Gamma,x:A\vdash b=b':B}
{\Gamma\vdash\lambda(x:A).b=\lambda(x:A').b':\Pi(x:A).B}\\
\frac{\Gamma\vdash f=f':\Pi(x:A).B\quad\Gamma\vdash a=a':A}
{\Gamma\vdash\operatorname{app}(f,a)=\operatorname{app}(f',a'):B[a/x]}\\
\frac{\Gamma\vdash a=a':A\quad\Gamma,x:A\vdash B:\mathsf{Ty}\quad\Gamma\vdash b=b':B[a/x]\quad\Gamma\vdash b':B[a'/x]}
{\Gamma\vdash\operatorname{pair}(a,b)=\operatorname{pair}(a',b'):\Sigma(x:A).B}\\
\frac{\Gamma\vdash P=P':\Sigma(x:A).B}
{\Gamma\vdash\operatorname{fst}(P)=\operatorname{fst}(P'):A\quad
\Gamma\vdash\operatorname{snd}(P)=\operatorname{snd}(P'):B[\operatorname{fst}(P)/x]}\\
\frac{\Gamma\vdash A=A':\mathsf{Ty}\quad\Gamma\vdash a=a':A}
{\Gamma\vdash\operatorname{refl}(A,a)=\operatorname{refl}(A',a'):\operatorname{Eq}_A(a,a)}.
\end{gathered}

\begin{gathered}
\frac{\Gamma\vdash A=A':\mathsf{Ty}\quad\Gamma,x:A\vdash B=B':\mathsf{Ty}\quad
\Gamma\vdash K_{A,x.B}(\vec a):T\quad\Gamma\vdash K_{A',x.B'}(\vec a):T'\quad\Gamma\vdash T=T':\mathsf{Ty}}
{\Gamma\vdash K_{A,x.B}(\vec a)=K_{A',x.B'}(\vec a):T}
\quad\bigl(K\in\{\operatorname{app},\operatorname{pair},\operatorname{fst},\operatorname{snd}\}\bigr).
\\
\frac{\Gamma\vdash A=A':\mathsf{Ty}\quad\Gamma,x:A\vdash B=B':\mathsf{Ty}\quad
\Gamma,x:A\vdash b:B\quad\Gamma,x:A'\vdash b:B'}
{\Gamma\vdash\lambda_{A,x.B}(x.b)=\lambda_{A',x.B'}(x.b):\Pi(x:A).B}.
\end{gathered}
